insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-so-144","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Warming a solvent generally","options":["raises $K_H$ and lowers gas solubility","lowers $K_H$ and raises gas solubility","leaves gas solubility untouched","ionises the dissolved gas"],"answer_index":0,"explanation":"Gas dissolution is exothermic, so $K_H$ increases and x falls as T rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"},{"id":"che-so-145","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A compact statement of Henry’s law for a sparingly soluble gas is","options":["$p = K_H x$","$p = K_H / x$","$p = x / K_H^2$","$\\pi = CRT$"],"answer_index":0,"explanation":"Partial pressure of the gas is proportional to its mole fraction in the solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law"},{"id":"che-so-146","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 298 K, $K_H$ for N2 in water is 8.0 × 10⁴ atm. Under 0.80 atm of nitrogen the dissolved mole fraction is","options":["1.0 × 10⁻⁵","8.0 × 10⁻⁴","0.80","1.0 × 10⁻³"],"answer_index":0,"explanation":"x = p / $K_H$ = 0.80 / 8.0 × 10⁴ = 1.0 × 10⁻⁵.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law"},{"id":"che-so-147","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two gases have $K_H$ values 2 × 10³ atm and 5 × 10⁴ atm. At the same partial pressure the more soluble gas is the one with","options":["$K_H$ = 2 × 10³ atm","$K_H$ = 5 × 10⁴ atm","equal solubility in both cases","neither gas dissolving"],"answer_index":0,"explanation":"Solubility falls as $K_H$ rises, so the smaller constant marks the more soluble gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law"},{"id":"che-so-148","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A mountaineer takes up less oxygen at high altitude mainly because","options":["the partial pressure of O2 in the air is lower","$K_H$ of oxygen becomes zero","blood volume instantly doubles","nitrogen is absent from the atmosphere"],"answer_index":0,"explanation":"Henry’s law: dissolved x(O2) tracks p(O2), which falls as total air pressure falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law"},{"id":"che-so-149","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"If the partial pressure of CO2 above a drink is doubled at constant temperature, the dissolved mole fraction of CO2","options":["doubles","halves","becomes four times","stays exactly the same"],"answer_index":0,"explanation":"x ∝ p at fixed T, so doubling p doubles the dissolved mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law"},{"id":"che-so-150","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dry air is 0.21 mole fraction oxygen. With $K_H$(O2) = 3.3 × 10⁷ torr and a total air pressure of 760 torr, dissolved x(O2) is nearest","options":["4.8 × 10⁻⁶","2.1 × 10⁻¹","3.3 × 10⁻⁷","1.6 × 10⁻⁴"],"answer_index":0,"explanation":"p(O2) = 0.21 × 760 = 160 torr; x = 160 / 3.3 × 10⁷ ≈ 4.8 × 10⁻⁶.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"henrys-law"},{"id":"che-so-151","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For volatile component A in an ideal liquid mixture, Raoult’s relation is written","options":["$p_A = p_A^\\circ x_A$","$p_A = p_A^\\circ / x_A$","$p_A = p_A^\\circ + x_A$","$p_A = K_H x_A$"],"answer_index":0,"explanation":"Partial pressure equals the pure-liquid vapour pressure times the liquid mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-152","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Total vapour pressure over an ideal binary liquid equals","options":["$p_A^\\circ x_A + p_B^\\circ x_B$","$p_A^\\circ + p_B^\\circ$","$x_A + x_B$","$K_H(x_A + x_B)$"],"answer_index":0,"explanation":"Each component contributes independently: $p_{\\mathrm{total}} = \\sum p_i^\\circ x_i$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-153","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dissolving a non-volatile solute in a pure solvent","options":["lowers the solvent vapour pressure","raises the solvent vapour pressure","leaves the vapour pressure unchanged","always doubles the vapour pressure"],"answer_index":0,"explanation":"Solvent mole fraction falls below 1, so $p = p^\\circ x_{\\mathrm{solvent}} < p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-154","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Vapour in equilibrium with an ideal A–B liquid is richer in the component that has the","options":["higher pure-liquid vapour pressure","lower pure-liquid vapour pressure","larger molar mass only","zero Henry constant"],"answer_index":0,"explanation":"The more volatile liquid (larger $p^\\circ$) contributes a larger partial pressure, so $y > x$ for that component.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-155","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A graph of total vapour pressure against liquid mole fraction for an ideal binary pair is","options":["the straight line joining $p_A^\\circ$ and $p_B^\\circ$","a curve with a maximum","a curve with a minimum","a parabola through the origin"],"answer_index":0,"explanation":"Ideal $p_{\\mathrm{total}}$ varies linearly between the two pure-liquid vapour pressures.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-156","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Dalton’s law applied to the vapour above a solution gives the vapour mole fraction of A as","options":["$y_A = p_A / p_{\\mathrm{total}}$","$y_A = x_A$","$y_A = p_A^\\circ$","$y_A = 1 - p_A$"],"answer_index":0,"explanation":"Each partial pressure is that component’s mole fraction in the gas times the total pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-157","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Raoult’s law for the solvent becomes exact in the limit of a solution that is","options":["very dilute in solute","very concentrated in solute","frozen solid","an emulsion"],"answer_index":0,"explanation":"The solvent then has $x \\approx 1$ and behaves as a nearly pure liquid obeying Raoult’s law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-158","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A closed flask of pure liquid A at equilibrium exerts","options":["its saturation vapour pressure $p_A^\\circ$","zero pressure","only $K_H$","osmotic pressure"],"answer_index":0,"explanation":"The equilibrium vapour pressure of the pure liquid is the $p^\\circ$ used in Raoult’s law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-159","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"When the liquid is pure A ($x_A = 1$), Raoult’s law reduces to","options":["$p_A = p_A^\\circ$","$p_A = 0$","$p_A = K_H$","$p_A = \\pi$"],"answer_index":0,"explanation":"The partial pressure of a pure liquid is just its own vapour pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-160","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two liquids that obey Raoult’s law at every composition are said to form","options":["an ideal solution","an azeotrope in every case","a colloid","a suspension"],"answer_index":0,"explanation":"Ideal solutions follow $p_i = p_i^\\circ x_i$ over the whole composition range.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-161","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A clear drop in vapour pressure is used as a colligative effect when the added solute is","options":["non-volatile (or far less volatile than the solvent)","more volatile than the solvent","a catalyst","always a noble gas"],"answer_index":0,"explanation":"Only then does the total pressure fall below $p^\\circ$ of the pure solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-162","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For an ideal mix the vapour mole fraction of A is related to the liquid composition by","options":["$y_A = (p_A^\\circ x_A) / p_{\\mathrm{total}}$","$y_A = x_A$","$y_A = p_A^\\circ$","$y_A = K_H x_A$"],"answer_index":0,"explanation":"Combine Raoult ($p_A = p_A^\\circ x_A$) with Dalton ($y_A = p_A / p_{\\mathrm{total}}$).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"},{"id":"che-so-163","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At a given temperature, the liquid with the larger $p^\\circ$ is described as","options":["more volatile","less volatile","non-volatile","ideal only"],"answer_index":0,"explanation":"Volatility tracks the equilibrium vapour pressure of the pure liquid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
insert into question_pyq_meta (question_id, appear_count, years, exams, verified) select question_id, appear_count, years, exams, verified from jsonb_to_recordset($meta$[{"question_id":"che-so-144","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-145","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-146","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-147","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-148","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-149","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-150","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-151","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-152","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-153","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-154","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-155","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-156","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-157","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-158","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-159","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-160","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-161","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-162","appear_count":0,"years":[],"exams":[],"verified":false},{"question_id":"che-so-163","appear_count":0,"years":[],"exams":[],"verified":false}]$meta$::jsonb) as t(question_id text, appear_count int, years int[], exams text[], verified boolean) on conflict (question_id) do 